// Picks the next DUE instagram item from Nathan's queue.
//
// This runs HOURLY, not once at noon. The laptop sleeps, and n8n's cron does not
// backfill a tick it slept through — a single daily trigger silently loses the
// day. Instead every hour asks "should something go out now?", guarded so it
// still posts at most once a day:
//
//   - already posted today  -> skip
//   - before IG_POST_HOUR   -> skip (don't post early)
//   - after IG_POST_UNTIL   -> skip (don't post at 3am after a long sleep)
//
// So on a normal day it posts at 12:00. If the machine was asleep until 15:00,
// it posts at 15:00. If it never woke inside the window, the item stays pending
// and goes out tomorrow — the queue drains a day later, nothing is lost.
//
// Times are local; TZ is set to Asia/Hong_Kong in .env.
const fs = require('fs');
const path = require('path');

const QUEUE_PATH =
  $env.TS_CONTENT_QUEUE ||
  'C:\\work\\OneTradingSocial\\Website\\automation\\n8n\\content-queue.json';
const LOG_PATH = path.join(path.dirname(QUEUE_PATH), 'post-log.jsonl');

const START_HOUR = Number($env.IG_POST_HOUR || 12);
const END_HOUR = Number($env.IG_POST_UNTIL_HOUR || 21);

const now = new Date();
const hour = now.getHours();
const todayKey = now.toLocaleDateString('en-CA'); // YYYY-MM-DD, local

const skip = (reason) => [{ json: { found: false, reason } }];

// Guard 1: one Instagram post per calendar day.
let postedToday = false;
try {
  for (const line of fs.readFileSync(LOG_PATH, 'utf8').split('\n')) {
    if (!line.trim()) continue;
    const e = JSON.parse(line);
    if (e.platform === 'instagram' && new Date(e.at).toLocaleDateString('en-CA') === todayKey) {
      postedToday = true;
      break;
    }
  }
} catch (err) {
  // No log yet — nothing has ever posted.
}
if (postedToday) return skip('Already posted to Instagram today (' + todayKey + ').');

// Guard 2: only inside the posting window.
if (hour < START_HOUR) return skip('Before the ' + START_HOUR + ':00 window (now ' + hour + ':00).');
if (hour >= END_HOUR) {
  return skip('Past the ' + END_HOUR + ':00 cutoff (now ' + hour + ':00) — leaving it for tomorrow.');
}

let queue;
try {
  queue = JSON.parse(fs.readFileSync(QUEUE_PATH, 'utf8'));
} catch (err) {
  throw new Error('Cannot read the content queue at ' + QUEUE_PATH + ': ' + err.message);
}

const due = (queue.items || [])
  .filter(
    (i) =>
      i.platform === 'instagram' &&
      i.status === 'pending' &&
      (i.imageUrl || i.videoUrl) &&
      (!i.scheduledFor || Date.parse(i.scheduledFor) <= now.getTime())
  )
  .sort((a, b) => {
    const ta = a.scheduledFor ? Date.parse(a.scheduledFor) : 0;
    const tb = b.scheduledFor ? Date.parse(b.scheduledFor) : 0;
    return ta - tb;
  });

if (due.length === 0) {
  return skip('No instagram item is pending, due, and carrying an imageUrl or videoUrl.');
}

const item = due[0];
const isReel = !item.imageUrl && !!item.videoUrl;

return [
  {
    json: {
      found: true,
      source: 'queue',
      itemId: item.id,
      mediaUrl: isReel ? item.videoUrl : item.imageUrl,
      mediaType: isReel ? 'REELS' : 'IMAGE',
      caption: item.text || '',
    },
  },
];

// Reads the long-lived token from the shared token file. Workflow 05 refreshes
// that file weekly — per-workflow static data cannot be shared between the two,
// which is why this lives on disk next to the content queue.
const fs = require('fs');
const path = require('path');

const QUEUE_PATH =
  $env.TS_CONTENT_QUEUE ||
  'C:\\work\\OneTradingSocial\\Website\\automation\\n8n\\content-queue.json';
const TOKEN_PATH = path.join(path.dirname(QUEUE_PATH), 'instagram-token.json');

const igUserId = $env.IG_USER_ID;
const base = ($env.IG_GRAPH_BASE || 'https://graph.instagram.com/v23.0').replace(/\/+$/, '');

if (!igUserId) throw new Error('IG_USER_ID is not set.');

let store = {};
try {
  store = JSON.parse(fs.readFileSync(TOKEN_PATH, 'utf8'));
} catch (err) {
  store = {};
}

// Seed from the env var the first time, then the file is the source of truth.
const token = store.accessToken || $env.IG_ACCESS_TOKEN;
if (!token) {
  throw new Error(
    'No Instagram access token. Complete the OAuth flow, put the long-lived token in IG_ACCESS_TOKEN, and run workflow 05 once (see README step 8).'
  );
}

if (!store.accessToken) {
  store.accessToken = token;
  store.seededAt = new Date().toISOString();
  try {
    fs.writeFileSync(TOKEN_PATH, JSON.stringify(store, null, 2), 'utf8');
  } catch (err) {
    // Non-fatal: posting can still proceed on the env-var token.
  }
}

// Instagram long-lived tokens die at 60 days and CANNOT be refreshed once
// expired — someone has to redo the OAuth consent by hand. Fail loudly rather
// than letting the account go quiet without explanation.
if (store.expiresAt) {
  const daysLeft = (Date.parse(store.expiresAt) - Date.now()) / 86400000;
  if (daysLeft < 0) {
    throw new Error(
      'The Instagram token expired on ' +
        store.expiresAt +
        '. It cannot be refreshed — redo the OAuth consent and reset IG_ACCESS_TOKEN.'
    );
  }
}

return [{ json: { token, igUserId, base, tokenPath: TOKEN_PATH } }];

// Publishing a container that is not FINISHED silently produces nothing, so
// fail loudly here instead.
const status = $json.status_code || '';
const container = $('Create Media Container').first().json;

if (container.error) {
  throw new Error(
    'Instagram rejected the container: ' +
      (container.error.message || JSON.stringify(container.error))
  );
}
if (!container.id) {
  throw new Error('No container id returned: ' + JSON.stringify(container).slice(0, 300));
}

if (status === 'ERROR') {
  throw new Error(
    'Instagram could not process the media. Most common causes: the image is not JPEG, the URL is not publicly reachable, or the aspect ratio is out of range. Detail: ' +
      ($json.status || 'none')
  );
}
if (status && status !== 'FINISHED') {
  throw new Error(
    'Container still ' + status + ' after the wait. Increase the Wait node for larger video.'
  );
}

return [{ json: { containerId: container.id, statusCode: status || 'FINISHED' } }];

const fs = require('fs');
const path = require('path');

const QUEUE_PATH =
  $env.TS_CONTENT_QUEUE ||
  'C:\\work\\OneTradingSocial\\Website\\automation\\n8n\\content-queue.json';
const LOG_PATH = path.join(path.dirname(QUEUE_PATH), 'post-log.jsonl');

const prep = $('Prepare Post').first().json;
const published = $json;

if (published.error) {
  throw new Error(
    'Instagram publish failed: ' +
      (published.error.message || JSON.stringify(published.error))
  );
}

const entry = {
  at: new Date().toISOString(),
  platform: 'instagram',
  source: prep.source,
  itemId: prep.itemId || null,
  mediaType: prep.mediaType,
  mediaId: published.id || null,
  captionChars: (prep.caption || '').length
};

if (prep.itemId) {
  try {
    const queue = JSON.parse(fs.readFileSync(QUEUE_PATH, 'utf8'));
    const target = (queue.items || []).find((i) => i.id === prep.itemId);
    if (target) {
      target.status = 'posted';
      target.postedAt = entry.at;
      fs.writeFileSync(QUEUE_PATH, JSON.stringify(queue, null, 2), 'utf8');
      entry.queueUpdated = true;
    }
  } catch (err) {
    entry.queueError = String(err.message || err);
  }
}

try {
  fs.appendFileSync(LOG_PATH, JSON.stringify(entry) + '\n', 'utf8');
} catch (err) {
  // The post already went out — never fail the run on logging.
}

return [{ json: entry }];
